ucs.falcon_logscale_query:
#event_simpleName=ProcessRollup2
| (
    (ImageFileName=/\\vssadmin\.exe$/i AND regex("delete.*shadows", field=CommandLine, flags="i"))
    OR (ImageFileName=/\\wmic\.exe$/i AND regex("shadowcopy.*delete", field=CommandLine, flags="i"))
    OR (ImageFileName=/\\wbadmin\.exe$/i AND regex("delete\s+(catalog|systemstatebackup|backup)", field=CommandLine, flags="i"))
    OR (ImageFileName=/\\bcdedit\.exe$/i AND regex("(recoveryenabled\s+no|bootstatuspolicy\s+ignoreallfailures)", field=CommandLine, flags="i"))
    OR (ImageFileName=/\\wevtutil\.exe$/i AND regex("\s(cl|clear-log)\s", field=CommandLine, flags="i"))
  )
| case {
    ImageFileName=/\\vssadmin\.exe$/i  | action := "vss_delete";
    ImageFileName=/\\wmic\.exe$/i      | action := "wmic_shadow_delete";
    ImageFileName=/\\wbadmin\.exe$/i   | action := "wbadmin_delete";
    ImageFileName=/\\bcdedit\.exe$/i   | action := "bcdedit_disable_recovery";
    ImageFileName=/\\wevtutil\.exe$/i  | action := "log_clear";
    *                                  | action := "other";
  }
| bucket(span=10m, field=@timestamp)
| groupBy([aid, ComputerName, _bucket], function=[collect([action]), count(field=action, distinct=true, as=distinct_actions), min(@timestamp, as=firstSeen), max(@timestamp, as=lastSeen)])
| distinct_actions >= 2
